package com.kartyavya.report.service; import com.kartyavya.contracts.RabbitTopology; import com.kartyavya.report.entity.OutboxEvent; import com.kartyavya.report.repository.OutboxRepository; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.amqp.core.Message; import org.springframework.amqp.core.MessageProperties; import java.nio.charset.StandardCharsets; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; @Component public class OutboxPublisher{private final OutboxRepository repo;private final RabbitTemplate rabbit;public OutboxPublisher(OutboxRepository r,RabbitTemplate t){repo=r;rabbit=t;}@Scheduled(fixedDelayString="${outbox.publish-delay-ms:2000}")@Transactional public void publish(){for(OutboxEvent e:repo.findTop50ByStatusOrderByCreatedAtAsc("PENDING")){try{MessageProperties properties=new MessageProperties();properties.setContentType(MessageProperties.CONTENT_TYPE_JSON);properties.setDeliveryMode(org.springframework.amqp.core.MessageDeliveryMode.PERSISTENT);rabbit.send(RabbitTopology.EXCHANGE,e.getRoutingKey(),new Message(e.getPayload().getBytes(StandardCharsets.UTF_8),properties));e.setStatus("PUBLISHED");e.setPublishedAt(Instant.now());}catch(Exception x){e.setAttempts(e.getAttempts()+1);e.setLastError(x.getMessage());if(e.getAttempts()>=10)e.setStatus("FAILED");}repo.save(e);}}}
